$("quiz-levels-hear").onclick=sayQuizLevels;
$("quiz-previous").onclick=()=>{stopSpeech();quizLevelPage=Math.max(0,quizLevelPage-1);quizLevelMessage="";renderQuizLevels();sayQuizLevels()};
$("quiz-next-page").onclick=()=>{stopSpeech();quizLevelPage++;quizLevelMessage="";renderQuizLevels();sayQuizLevels()};
$("quiz-quit").onclick=()=>{window.clearTimeout(quizResetTimer);quizLevelPage=Math.floor((quizLevel-1)/10);quizLevelMessage="";showQuizLevels()};
$("quiz-hear").onclick=hearQuizQuestion;
$("quiz-clear").onclick=()=>{if(quizAnswered)return;window.clearTimeout(quizResetTimer);stopSpeech();quizPlaced=[];renderQuizSentence()};
$("quiz-next").onclick=advanceQuiz;
document.addEventListener("pointerdown",()=>{if(!pendingSpeech||muted)return;const list=pendingSpeech;pendingSpeech=null;say(list)},true);
$("addition-levels-back").onclick=()=>{stopSpeech();showMathMode()};
$("addition-level-hear").onclick=sayAdditionLevels;
$("addition-level-previous").onclick=()=>{stopSpeech();mathLevelPages[mathTopic]=Math.max(0,mathLevelPages[mathTopic]-1);showAdditionLevels()};
$("addition-level-next").onclick=()=>{stopSpeech();mathLevelPages[mathTopic]++;showAdditionLevels()};
$("addition-menu-back").onclick=()=>{stopSpeech();if(mathFlow==="learning")showMathMode();else showAdditionLevels()};
$("addition-hear").onclick=()=>{if(additionMode==="learn"&&additionPickerStage==="first")say([`Choose the first number for ${mathTopic.toLowerCase()}.`]);else if(additionMode==="learn"&&additionPickerStage==="second")say([mathSecondNumberPrompt()]);else additionSayQuestion()};
$("addition-choose-numbers").onclick=chooseDifferentMathNumbers;
$("addition-next").onclick=()=>{stopSpeech();renderAdditionQuestion();additionSayQuestion()};
$("addition-practice").onclick=()=>{stopSpeech();additionMode="exercise";renderAdditionQuestion();additionSayQuestion()};
$("addition-builder-back").onclick=()=>{stopSpeech();additionMode="learn";$("addition-practice").hidden=true;chooseDifferentMathNumbers()};
$("chg").onclick=()=>{stopSpeech();if(selectedLanguage==="Telugu"||selectedLanguage==="Hindi"){showNativeTypes();return}if(selectedLanguage==="English"){showEnglishTypes();return}showLanguage()};
$("lang").onclick=()=>{if("speechSynthesis"in window)speechSynthesis.cancel();try{sessionStorage.removeItem("learningLanguage")}catch(e){}selectedLanguage="";document.documentElement.lang="en";showLanguage()};
$("again").onclick=()=>say(last.length?last:["Tap a letter"]);
document.addEventListener("keydown",e=>{if($("app").hidden||e.ctrlKey||e.metaKey||e.altKey)return;const k=e.key;
 if(selectedLanguage==="Telugu"){if(teluguWords&&teluguWords[k])showTeluguLetter(k);else if(k==="Enter")$("again").click();return}
 if(selectedLanguage==="Hindi"){if(hindiWords&&hindiWords[k])showHindiLetter(k);else if(k==="Enter")$("again").click();return}
 if(/^[a-z]$/i.test(k))letter(k.toUpperCase());else if(/^\d$/.test(k))number(k=="0"?10:+k);else if(k==="Enter")$("again").click()});
startSplash();

// Offline support + installability (service worker is generated by the build step)
if("serviceWorker"in navigator&&location.protocol!=="file:"){
 // Reload once when a newer service worker takes over, so an outdated cached copy is replaced straight away.
 let reloaded=false;if(navigator.serviceWorker.controller)navigator.serviceWorker.addEventListener("controllerchange",()=>{if(!reloaded){reloaded=true;location.reload()}});
 window.addEventListener("load",()=>navigator.serviceWorker.register("sw.js",{updateViaCache:"none"}).then(r=>r.update()).catch(()=>{}))}
